#include <iostream>
#include <optional>

// Demonstrating the legacy pattern (Error-Prevention Tip 17.1)
// where a return code / sentinel value can easily be misused.
bool legacy_divide(int numerator, int denominator, double& result) {
    if (denominator == 0) {
        return false; // Error indicator
    }
    result = static_cast<double>(numerator) / denominator;
    return true;
}

int main() {
    double ans = 0.0;
    int a = 10;
    int b = 0;

    if (!legacy_divide(a, b, ans)) {
        std::cout << "Legacy check: denominator was zero, cannot divide!\n";
    }
    return 0;
}

#include <iostream>
#include <stdexcept>

// Fig. 17.1: DivideByZeroException definition
class DivideByZeroException : public std::runtime_error {
public:
    DivideByZeroException()
        : std::runtime_error("attempted to divide by zero") {}
};

// Fig. 17.2: quotient function
double quotient(int numerator, int denominator) {
    if (denominator == 0) {
        throw DivideByZeroException();
    }
    return static_cast<double>(numerator) / denominator;
}

int main() {
    int num = 100;
    int den = 0;

    try {
        std::cout << "Calling quotient(" << num << ", " << den << ")\n";
        double result = quotient(num, den);
        // The following line is skipped if an exception is thrown
        std::cout << "The quotient is: " << result << "\n";
    }
    catch (const DivideByZeroException& divideByZeroException) {
        std::cout << "Exception occurred: "
                  << divideByZeroException.what() << "\n";
    }

    return 0;
}
